import time
import numpy as np

N = 26
LIMIT = 27.0


def _lp_radii(centers):
    n = len(centers)
    bnd = np.minimum.reduce((centers[:, 0], centers[:, 1],
                             1.0 - centers[:, 0], 1.0 - centers[:, 1]))
    bnd = np.maximum(bnd, 0.0)
    try:
        from scipy.optimize import linprog
        rows = []
        rhs = []
        for i in range(n):
            for j in range(i + 1, n):
                a = np.zeros(n)
                a[i] = 1.0
                a[j] = 1.0
                rows.append(a)
                rhs.append(float(np.linalg.norm(centers[i] - centers[j])))
        res = linprog(-np.ones(n), A_ub=np.array(rows), b_ub=np.array(rhs),
                      bounds=[(0.0, float(x)) for x in bnd], method="highs")
        if res.success and np.all(np.isfinite(res.x)):
            return np.maximum(res.x, 0.0)
    except Exception:
        pass
    r = bnd.copy()
    for _ in range(6):
        for i in range(n):
            for j in range(i + 1, n):
                d = np.linalg.norm(centers[i] - centers[j])
                s = r[i] + r[j]
                if s > d and s > 0:
                    f = d / s
                    r[i] *= f
                    r[j] *= f
    return r


def _valid(c, r):
    if c.shape != (N, 2) or r.shape != (N,):
        return False
    if not (np.all(np.isfinite(c)) and np.all(np.isfinite(r))):
        return False
    if np.any(r < -1e-10):
        return False
    if np.any(c[:, 0] < r - 1e-8) or np.any(c[:, 0] > 1 - r + 1e-8):
        return False
    if np.any(c[:, 1] < r - 1e-8) or np.any(c[:, 1] > 1 - r + 1e-8):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            if np.linalg.norm(c[i] - c[j]) + 1e-8 < r[i] + r[j]:
                return False
    return True


def _add_candidate(c, best):
    if len(c) != N:
        return best
    c = np.asarray(c, dtype=float)
    c = np.clip(c, 0.0, 1.0)
    r = _lp_radii(c)
    if _valid(c, r) and float(np.sum(r)) > best[2]:
        best = (c.copy(), r.copy(), float(np.sum(r)))
    return best


def _row_pattern(counts, phase=0.0):
    pts = []
    m = len(counts)
    for i, k in enumerate(counts):
        y = (i + 0.5) / m
        off = (phase if i % 2 else 0.0) / max(k, 1)
        for j in range(k):
            pts.append(((j + 0.5) / k + off, y))
    return np.array(pts[:N], dtype=float)


def _grid5():
    pts = []
    for y in np.linspace(0.1, 0.9, 5):
        for x in np.linspace(0.1, 0.9, 5):
            pts.append((x, y))
    pts.append((0.0, 0.0))
    return np.array(pts, dtype=float)


def _polish(c, r, deadline):
    if time.time() > deadline - 8.0:
        return c, r
    try:
        from scipy.optimize import minimize
    except Exception:
        return c, r

    x0 = np.concatenate([c.ravel(), r])
    pairs = [(i, j) for i in range(N) for j in range(i + 1, N)]

    def unpack(z):
        cc = z[:2 * N].reshape(N, 2)
        rr = z[2 * N:]
        return cc, rr

    def obj(z):
        return -float(np.sum(z[2 * N:]))

    def cons(z):
        cc, rr = unpack(z)
        out = []
        out.extend(rr)
        out.extend(cc[:, 0] - rr)
        out.extend(1.0 - cc[:, 0] - rr)
        out.extend(cc[:, 1] - rr)
        out.extend(1.0 - cc[:, 1] - rr)
        for i, j in pairs:
            out.append(np.linalg.norm(cc[i] - cc[j]) - rr[i] - rr[j])
        return np.array(out, dtype=float)

    try:
        res = minimize(obj, x0, method="SLSQP",
                       bounds=[(0.0, 1.0)] * (2 * N) + [(0.0, 0.5)] * N,
                       constraints={"type": "ineq", "fun": cons},
                       options={"maxiter": 100, "ftol": 1e-10, "disp": False})
        if res.success and np.all(np.isfinite(res.x)):
            cc, rr = unpack(res.x)
            cc = np.clip(cc, 0.0, 1.0)
            rr = np.maximum(rr, 0.0)
            if _valid(cc, rr) and np.sum(rr) > np.sum(r):
                return cc, rr
    except Exception:
        pass
    return c, r


def construct_packing():
    start = time.time()
    deadline = start + LIMIT
    c0 = _grid5()
    r0 = np.full(N, 0.1)
    r0[-1] = 0.0
    best = (c0, r0, float(np.sum(r0)))

    patterns = [
        [5, 5, 5, 5, 5, 1],
        [4, 5, 4, 5, 4, 4],
        [5, 4, 5, 4, 5, 3],
        [6, 5, 5, 5, 5],
        [6, 5, 4, 5, 6],
        [4, 4, 5, 5, 4, 4],
        [3, 5, 5, 5, 5, 3],
        [4, 6, 5, 6, 5],
    ]
    for counts in patterns:
        if time.time() > deadline - 10.0:
            break
        for ph in (0.0, 0.5):
            best = _add_candidate(_row_pattern(counts, ph), best)

    c, r = best[0].copy(), best[1].copy()
    c, r = _polish(c, r, deadline)
    if not _valid(c, r):
        c, r = best[0].copy(), best[1].copy()

    r = np.maximum(r, 0.0) * (1.0 - 1e-9)
    if not _valid(c, r):
        c, r = c0, r0 * (1.0 - 1e-9)
    return c.astype(float), r.astype(float), float(np.sum(r))


def run_packing():
    centers, radii, sum_radii = construct_packing()
    return centers, radii, sum_radii


def visualize(centers, radii):
    import matplotlib.pyplot as plt
    from matplotlib.patches import Circle
    fig, ax = plt.subplots(figsize=(8, 8))
    ax.set_xlim(0, 1)
    ax.set_ylim(0, 1)
    ax.set_aspect("equal")
    for i, (p, r) in enumerate(zip(centers, radii)):
        ax.add_patch(Circle(p, r, alpha=0.45))
        ax.text(p[0], p[1], str(i), ha="center", va="center", fontsize=8)
    plt.title("sum radii %.12f" % float(np.sum(radii)))
    plt.show()


if __name__ == "__main__":
    centers, radii, reported_sum = run_packing()
    print(reported_sum)
